ControlPropertyState.AutoRuleBindingString:
If(
    !IsBlank(conDashboardHeader_SearchBar_79.Text),
    Patch(
        'VCDS — TDR Chat',
        Defaults('VCDS — TDR Chat'),
        {
            'TDR ID (Lookup)': {
                Value: Text(varTDRItem.ID),
                Id: varTDRItem.ID
            },
            'TDR ID': varTDRItem.ID,
            Message: conDashboardHeader_SearchBar_79.Text,
            Mentions: JSON(Table(ForAll(TravelersCB_6.SelectedItems, {FullName: Concatenate(GivenName, " ", Surname), Email: Mail})))
        }
    );
    Reset(conDashboardHeader_SearchBar_79);
    Reset(TravelersCB_6);
    Refresh('VCDS — TDR Chat'),
    Notify("ERROR: Message cannot be blank", NotificationType.Error, 4000)
)
